import math

def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, v in enumerate(a):
        prefix[i + 1] = prefix[i] + v

    hull: list[int] = []

    def cross(i: int, j: int, m: int) -> int:
        return (j - i) * (prefix[m] - prefix[i]) - (prefix[j] - prefix[i]) * (m - i)

    def slope_ge(i: int, j: int, r: int) -> bool:
        return (prefix[r] - prefix[i]) * (r - j) >= (prefix[r] - prefix[j]) * (r - i)

    best_num = -1
    best_den = 1

    for r in range(k, n + 1):
        idx = r - k
        while len(hull) >= 2 and cross(hull[-2], hull[-1], idx) <= 0:
            hull.pop()
        hull.append(idx)

        lo = 0
        hi = len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_ge(hull[mid], hull[mid + 1], r):
                hi = mid
            else:
                lo = mid + 1

        left = hull[lo]
        num = prefix[r] - prefix[left]
        den = r - left
        if best_num < 0 or num * best_den > best_num * den:
            best_num = num
            best_den = den

    g = math.gcd(best_num, best_den)
    return [best_num // g, best_den // g]
